/* eslint-disable no-restricted-syntax, no-invalid-this, stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getAlign = require( './align/get.js' );
var setAlign = require( './align/set.js' );

var getBounds = require( './bounds/get.js' );
var setBounds = require( './bounds/set.js' );

var getCenter = require( './center/get.js' );
var setCenter = require( './center/set.js' );
var getColumns = require( './columns/get.js' );
var setColumns = require( './columns/set.js' );

var getFooterBand = require( './footer-band/get.js' );
var setFooterBand = require( './footer-band/set.js' );

var getHeaderBand = require( './header-band/get.js' );
var setHeaderBand = require( './header-band/set.js' );

var getOffset = require( './offset/get.js' );
var setOffset = require( './offset/set.js' );

var getPadding = require( './padding/get.js' );
var setPadding = require( './padding/set.js' );
var getProperties = require( './properties/get.js' );

var getTitleAnchor = require( './title-anchor/get.js' );
var setTitleAnchor = require( './title-anchor/set.js' );
var getTitleBand = require( './title-band/get.js' );
var setTitleBand = require( './title-band/set.js' );


// VARIABLES //

var debug = logger( 'vega:layout:main' );


// MAIN //

/**
* Layout constructor.
*
* @constructor
* @param {Options} [options] - constructor options
* @param {(string|Object)} [options.align] - grid alignment to apply to rows and columns
* @param {string} [options.bounds] - bounds calculation method to use for determining the extent of a sub-plot
* @param {(boolean|Object)} [options.center] - boolean flag (or row/column object) indicating whether to center child elements within their respective rows and columns
* @param {number} [options.columns] - number of columns to include in the grid layout
* @param {(number|Object|null)} [options.footerBand] - alignment of footers relative to their bands
* @param {(number|Object|null)} [options.headerBand] - alignment of headers relative to their bands
* @param {(number|Object)} [options.offset] - offset (in pixels) by which to displace header, footer, and title cells from the edges of the grid
* @param {(number|Object)} [options.padding] - padding (in pixels) between the rows and columns of the grid
* @param {(string|Object)} [options.titleAnchor] - anchor position for placing titles relative to their bands
* @param {(number|Object)} [options.titleBand] - alignment of titles relative to their bands
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {Layout} layout instance
*
* @example
* var layout = new Layout({
*     'columns': 2
* });
* // returns <Layout>
*/
function Layout( options ) {
	var nargs;
	var opts;
	var keys;
	var v;
	var k;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof Layout ) ) {
		if ( nargs ) {
			return new Layout( options );
		}
		return new Layout();
	}
	EventEmitter.call( this );

	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}
	if ( nargs ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		// Validate provided options by attempting to assign option values to corresponding fields...
		for ( i = 0; i < properties.length; i++ ) {
			k = properties[ i ];
			if ( !hasProp( options, k ) ) {
				continue;
			}
			v = options[ k ];
			try {
				this[ k ] = v;
			} catch ( err ) {
				debug( 'Encountered an error. Error: %s', err.message );

				// FIXME: retain thrown error type
				throw new Error( transformErrorMessage( err.message ) );
			}
		}
	}
	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( Layout, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof Layout
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( Layout, 'name', 'Layout' );

/**
* Grid alignment to apply to rows and columns.
*
* @name align
* @memberof Layout.prototype
* @type {(string|Object)}
* @default 'none'
*
* @example
* var layout = new Layout({
*     'align': 'each'
* });
*
* var v = layout.align;
* // returns 'each'
*/
setReadWriteAccessor( Layout.prototype, 'align', getAlign, setAlign );

/**
* Bounds calculation method to use for determining the extent of a sub-plot.
*
* @name bounds
* @memberof Layout.prototype
* @type {string}
* @default 'full'
*
* @example
* var layout = new Layout({
*     'bounds': 'flush'
* });
*
* var v = layout.bounds;
* // returns 'flush'
*/
setReadWriteAccessor( Layout.prototype, 'bounds', getBounds, setBounds );

/**
* Boolean flag (or row/column object) indicating whether to center child elements within their respective rows and columns.
*
* @name center
* @memberof Layout.prototype
* @type {(boolean|Object)}
* @default false
*
* @example
* var layout = new Layout({
*     'center': true
* });
*
* var v = layout.center;
* // returns true
*/
setReadWriteAccessor( Layout.prototype, 'center', getCenter, setCenter );

/**
* Number of columns to include in the grid layout.
*
* @name columns
* @memberof Layout.prototype
* @type {(number|void)}
*
* @example
* var layout = new Layout({
*     'columns': 2
* });
*
* var v = layout.columns;
* // returns 2
*/
setReadWriteAccessor( Layout.prototype, 'columns', getColumns, setColumns );

/**
* Alignment (in the range `[0,1]`) of footers relative to their bands.
*
* @name footerBand
* @memberof Layout.prototype
* @type {(number|Object|null)}
* @default null
*
* @example
* var layout = new Layout({
*     'footerBand': 0.5
* });
*
* var v = layout.footerBand;
* // returns 0.5
*/
setReadWriteAccessor( Layout.prototype, 'footerBand', getFooterBand, setFooterBand );

/**
* Alignment (in the range `[0,1]`) of headers relative to their bands.
*
* @name headerBand
* @memberof Layout.prototype
* @type {(number|Object|null)}
* @default null
*
* @example
* var layout = new Layout({
*     'headerBand': 0.5
* });
*
* var v = layout.headerBand;
* // returns 0.5
*/
setReadWriteAccessor( Layout.prototype, 'headerBand', getHeaderBand, setHeaderBand );

/**
* Offset (in pixels) by which to displace header, footer, and title cells from the edges of the grid.
*
* @name offset
* @memberof Layout.prototype
* @type {(number|Object)}
* @default 0
*
* @example
* var layout = new Layout({
*     'offset': 10
* });
*
* var v = layout.offset;
* // returns 10
*/
setReadWriteAccessor( Layout.prototype, 'offset', getOffset, setOffset );

/**
* Padding (in pixels) between the rows and columns of the grid.
*
* @name padding
* @memberof Layout.prototype
* @type {(number|Object|void)}
*
* @example
* var layout = new Layout({
*     'padding': 5
* });
*
* var v = layout.padding;
* // returns 5
*/
setReadWriteAccessor( Layout.prototype, 'padding', getPadding, setPadding );

/**
* Layout properties.
*
* @name properties
* @memberof Layout.prototype
* @type {Array<string>}
*
* @example
* var layout = new Layout({
*     'columns': 2
* });
*
* var v = layout.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( Layout.prototype, 'properties', getProperties );

/**
* Anchor position for placing titles relative to their bands.
*
* @name titleAnchor
* @memberof Layout.prototype
* @type {(string|Object)}
* @default 'start'
*
* @example
* var layout = new Layout({
*     'titleAnchor': 'end'
* });
*
* var v = layout.titleAnchor;
* // returns 'end'
*/
setReadWriteAccessor( Layout.prototype, 'titleAnchor', getTitleAnchor, setTitleAnchor );

/**
* Alignment (in the range `[0,1]`) of titles relative to their bands.
*
* @name titleBand
* @memberof Layout.prototype
* @type {(number|Object)}
* @default 0.5
*
* @example
* var layout = new Layout({
*     'titleBand': 0.5
* });
*
* var v = layout.titleBand;
* // returns 0.5
*/
setReadWriteAccessor( Layout.prototype, 'titleBand', getTitleBand, setTitleBand );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof Layout.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var layout = new Layout({
*     'columns': 2
* });
*
* var v = layout.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( Layout.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = Layout;
